package com.cyberpath.learning;
import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
/** Separate immutable file payloads and journal records from the frequently-saved workspace. */
public final class LocalLibrary {
 private static final Object LOCK=AppFiles.LOCK;
 private static File file(Context c,String key)throws IOException{if(!key.matches("(asset|journal)-[A-Za-z0-9_-]{1,100}"))throw new IOException("Invalid library record");File dir=new File(ProfileFiles.root(c),"studio-library");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Could not create the local library");return new File(dir,key+".json");}
 public static void put(Context c,String key,String value)throws Exception{synchronized(LOCK){byte[] bytes=value.getBytes(StandardCharsets.UTF_8);if(bytes.length>40_000_000)throw new IOException("File exceeds the local item size limit");new JSONObject(value);AtomicFile f=new AtomicFile(file(c,key));FileOutputStream out=null;try{out=f.startWrite();out.write(bytes);f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}}
 public static String get(Context c,String key)throws Exception{synchronized(LOCK){AtomicFile f=new AtomicFile(file(c,key));if(!f.getBaseFile().exists())return"";try(InputStream in=f.openRead()){return new String(AppFiles.readBounded(in,40_000_000),StandardCharsets.UTF_8);}}}
 private static boolean references(Object value,String id,int depth)throws Exception{if(depth>100)throw new IOException("Content is nested too deeply.");if(value instanceof JSONObject){JSONObject o=(JSONObject)value;if(id.equals(o.optString("assetId")))return true;JSONArray ids=o.optJSONArray("assetIds");if(ids!=null)for(int n=0;n<ids.length();n++)if(id.equals(ids.optString(n)))return true;java.util.Iterator<String> keys=o.keys();while(keys.hasNext())if(references(o.get(keys.next()),id,depth+1))return true;}else if(value instanceof JSONArray){JSONArray rows=(JSONArray)value;for(int n=0;n<rows.length();n++)if(references(rows.get(n),id,depth+1))return true;}return false;}
 public static void deleteUnused(Context c,String key)throws Exception{synchronized(LOCK){if(!key.startsWith("asset-"))throw new IOException("Only unused attachments can be freed.");String id=key.substring(6);JSONObject w=AppFiles.workspace(c),l=w.getJSONObject("learning");JSONArray active=l.optJSONArray("assets"),archived=l.optJSONObject("dataSafety")==null?null:l.getJSONObject("dataSafety").optJSONArray("archivedAssets");for(JSONArray rows:new JSONArray[]{active,archived})if(rows!=null)for(int n=0;n<rows.length();n++)if(id.equals(rows.getJSONObject(n).optString("id")))throw new IOException("File is still in the workspace.");if(references(w,id,0))throw new IOException("This file is used by content.");AtomicFile f=new AtomicFile(file(c,key));f.delete();if(f.getBaseFile().exists())throw new IOException("The file could not be freed.");}}
 public static JSONArray ids(Context c,String prefix)throws Exception{synchronized(LOCK){if(!prefix.equals("asset-")&&!prefix.equals("journal-"))throw new IOException("Invalid library collection");File[] files=new File(ProfileFiles.root(c),"studio-library").listFiles();JSONArray result=new JSONArray();if(files!=null)for(File f:files){String n=f.getName();if(n.startsWith(prefix)&&n.endsWith(".json"))result.put(n.substring(prefix.length(),n.length()-5));}return result;}}
 public static JSONObject backup(Context c,JSONObject workspace)throws Exception{JSONObject result=new JSONObject().put("format","cyberpath-workspace").put("version",2).put("exportedAt",Instant.now().toString()).put("workspace",workspace);JSONArray files=new JSONArray(),history=new JSONArray();JSONObject learning=workspace.optJSONObject("learning");JSONArray assets=learning==null?null:learning.optJSONArray("assets");if(learning!=null&&learning.optJSONObject("dataSafety")!=null){JSONArray archived=learning.getJSONObject("dataSafety").optJSONArray("archivedAssets");assets=assets==null?new JSONArray():new JSONArray(assets.toString());if(archived!=null)for(int i=0;i<archived.length();i++)assets.put(archived.get(i));}if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject metadata=assets.getJSONObject(i);String raw=get(c,"asset-"+metadata.getString("id"));if(raw.isEmpty())throw new IOException("A referenced attachment is unavailable: "+metadata.optString("name"));files.put(new JSONObject(raw));}JSONArray ids=ids(c,"journal-");Set<String> saved=new HashSet<>();for(int i=0;i<ids.length();i++){String raw=get(c,"journal-"+ids.getString(i));if(!raw.isEmpty()){JSONObject event=new JSONObject(raw);history.put(event);saved.add(event.getString("id"));}}JSONArray pending=learning==null?null:learning.optJSONArray("pendingHistory");if(pending!=null)for(int i=0;i<pending.length();i++){JSONObject event=pending.getJSONObject(i);if(saved.add(event.getString("id")))history.put(event);}return result.put("localFiles",files).put("activityHistory",history);}
}
